messages.content:
:root {
  --bg: #0c1f17;
  --surface: #143027;
  --accent: #10b981;
  --accent-2: #34d399;
  --text: #ecfdf5;
  --muted: #9cb8ac;
  --radius: 6px;
  --shadow: 0 4px 6px rgba(0,0,0,.1);
  --font: 'Inter', system-ui, sans-serif;
}
.card {
  font-family: var(--font);
  background: var(--surface);
  color: var(--text);
  border-radius: var(--radius);
  padding: 1.75rem;
  box-shadow: var(--shadow);
  transition: transform .3s ease, box-shadow .3s ease;
  max-width: 320px;
}
.card:hover { transform: translateY(-6px); box-shadow: 0 24px 48px rgba(0,0,0,.3); }
.card__icon {
  width: 48px; height: 48px;
  display: grid; place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #fff; font-size: 1.5rem;
  margin-bottom: 1rem;
}
.card__title { margin: 0 0 .5rem; font-size: 1.25rem; }
.card__body { margin: 0; color: var(--muted); line-height: 1.6; }

:root {
  --bg: #0a1929;
  --surface: #102a43;
  --accent: #0ea5e9;
  --accent-2: #06b6d4;
  --text: #e0f2fe;
  --muted: #94a3b8;
  --radius: 6px;
  --shadow: 0 20px 40px rgba(0,0,0,.25);
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}
