.card__title { margin: 0 0 .5rem; font-size: 1.25rem; }
.card__body { margin: 0; color: var(--muted); line-height: 1.6; }

:root {
  --bg: #1a1110;
  --surface: #2b1d1a;
  --accent: #f97316;
  --accent-2: #ef4444;
  --text: #fef3ec;
  --muted: #b8a99c;
  --radius: 10px;
  --shadow: 0 1px 3px rgba(0,0,0,.12), 0 1px 2px rgba(0,0,0,.24);
  --font: 'Inter', system-ui, sans-serif;
}
.btn {
  font-family: var(--font);
  padding: .75rem 1.75rem;
  border: none;
  border-radius: var(--radius);
  color: #fff;
  font-weight: 600;
  cursor: pointer;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  background-size: 200% 200%;
  box-shadow: var(--shadow);
  transition: transform .2s ease, background-position .4s ease;
}
.btn:hover { transform: translateY(-2px); background-position: right center; }
.btn:focus-visible { outline: 3px solid var(--accent-2); outline-offset: 2px; }

